// 以下测试向量由 salesforce/jarm 的参考实现 jarm.py 生成：探测报文在随机字段确定的
// 条件下逐字节比对；响应解析与指纹折算覆盖正常、缺扩展、告警、非 TLS 与截断的响应。

// fixedRandom 与生成向量时替换的随机源一致：字节依次递增，GREASE 依次取表中的值。
type fixedRandom struct{ next, choice int }

func (r *fixedRandom) bytes(n int) []byte {
	out := make([]byte, n)
	for i := range out {
		out[i] = byte(r.next + i)
	}
	r.next = (r.next + n) % 256
	return out
}

func (r *fixedRandom) grease() uint16 {
	value := jarmGrease[r.choice%len(jarmGrease)]
	r.choice++
	return value
}

