func TestJARMClientHelloMatchesReference(t *testing.T) {
	for i, probe := range jarmProbes {
		got := hex.EncodeToString(jarmClientHello("example.com", probe, &fixedRandom{}))
		if got != jarmHelloVectors[i] {
			t.Fatalf("第 %d 个探测报文与参考实现不同:\n got %s\nwant %s", i+1, got, jarmHelloVectors[i])
		}
	}
}

func TestJARMParseMatchesReference(t *testing.T) {
	for _, tc := range jarmParseVectors {
		packet, err := hex.DecodeString(tc.packet)
		if err != nil {
			t.Fatal(err)
		}
		if got := jarmParse(packet); got != tc.raw {
			t.Fatalf("%s: %q != %q", tc.name, got, tc.raw)
		}
	}
	if got := jarmParse(nil); got != "|||" {
		t.Fatalf("空响应: %q", got)
	}
}

func TestJARMHashMatchesReference(t *testing.T) {
	for _, tc := range jarmHashVectors {
		if got := JARMHash(tc.raw); got != tc.hash {
			t.Fatalf("%q: %s != %s", tc.raw, got, tc.hash)
		}
	}
	if len(jarmEmpty) != 62 {
		t.Fatal("空指纹必须是 62 位")
	}
}

// 对本机 TLS 服务端到端计算：每个探测都是一次连接，指纹稳定且不是空指纹；
// 非 TLS 服务得到 62 个 0（参考实现对没有以 TLS 响应的目标的结果）。
func TestJARMAgainstLocalServers(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	counted := &countingListener{Listener: ln}
	server := httptest.NewUnstartedServer(http.NotFoundHandler())
	server.Listener = counted
	// 不支持的探测会让服务端记录握手失败，这是预期行为，不输出到测试日志。
	server.Config.ErrorLog = log.New(io.Discard, "", 0)
	server.TLS = &tls.Config{MinVersion: tls.VersionTLS12}
	server.StartTLS()
	defer server.Close()
	u, _ := url.Parse(server.URL)
	client := NewHTTPClient()
	defer client.Close()
	first, err := client.JARM(context.Background(), u.Hostname(), u.Port(), OptionsRequest{Timeout: 3 * time.Second})
	if err != nil {
		t.Fatal(err)
	}
	second, _ := client.JARM(context.Background(), u.Hostname(), u.Port(), OptionsRequest{Timeout: 3 * time.Second})
	if len(first) != 62 || first == jarmEmpty || first != second || counted.conns.Load() != 20 {
		t.Fatalf("jarm=%s/%s conns=%d", first, second, counted.conns.Load())
	}

	plain := httptest.NewServer(http.NotFoundHandler())
	defer plain.Close()
	p, _ := url.Parse(plain.URL)
	if got, err := client.JARM(context.Background(), p.Hostname(), p.Port(), OptionsRequest{Timeout: 3 * time.Second}); err != nil || got != jarmEmpty {
		t.Fatalf("非 TLS 服务: %s %v", got, err)
	}

	// 只接受连接、从不应答的服务：读取超时按参考实现记为空指纹。
	silent, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer silent.Close()
	go func() {
		for {
			conn, err := silent.Accept()
			if err != nil {
				return
			}
			go func() { _, _ = io.Copy(io.Discard, conn) }()
		}
	}()
	host, port, _ := net.SplitHostPort(silent.Addr().String())
	if got, err := client.JARM(context.Background(), host, port, OptionsRequest{Timeout: 200 * time.Millisecond}); err != nil || got != jarmEmpty {
		t.Fatalf("超时: %s %v", got, err)
	}
}

// 网络策略拒绝目标时不发出任何探测。
func TestJARMRespectsPolicy(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	counted := &countingListener{Listener: ln}
	defer counted.Close()
	go func() {
		for {
			conn, err := counted.Accept()
			if err != nil {
				return
			}
			_ = conn.Close()
		}
	}()
	host, port, _ := net.SplitHostPort(ln.Addr().String())
	client := NewHTTPClient()
	defer client.Close()
	var kinds []RequestKind
	ctx := client.WithPolicy(context.Background(), Policy{CheckTarget: func(_ context.Context, request TargetRequest) error {
		kinds = append(kinds, request.Kind)
		return errors.New("blocked")
	}})
	if _, err := client.JARM(ctx, host, port, OptionsRequest{Timeout: time.Second}); err == nil || !strings.Contains(err.Error(), "blocked") {
		t.Fatalf("应被拒绝: %v", err)
	}
	if counted.conns.Load() != 0 || len(kinds) != 1 || kinds[0] != RequestTLS {
		t.Fatalf("conns=%d kinds=%v", counted.conns.Load(), kinds)
	}
}
